  ('nutricao-saude-coletiva-atencao-primaria', true, 'CFN/CRN', 'CRN', 'Lei 8.234/1991, arts. 1º e 3º, VII; Res. CFN 600/2018 (Saúde Coletiva); Res. CFN 689/2021, art. 3º, XXII e XVIII (título)', array['documento_selfie', 'cadastro_fiscal', 'registro_profissional']::public.verification_step[], false, 'sob_consulta_juridica'::public.billing_model, true, false, 'autonomo_ou_empresa'::public.provider_kind, false, array['hora', 'mes', 'projeto', 'visita']::public.price_unit[], array['estabelecimento', 'empresa_cliente', 'externo']::public.service_location[], 'Programas de saúde para comunidades, empresas e municípios, inclusive comunidades indígenas, quilombolas e ribeirinhas; exige CRN ativo. Vagas do SUS são por concurso ou contrato público.', 'a_confirmar', array['https://sisnormas.cfn.org.br/viewPage.html?id=600', 'https://sisnormas.cfn.org.br/viewPage.html?id=689']::text[]),
