  ('consultor-seguranca-dos-alimentos', false, '', '', '', array['documento_selfie', 'cadastro_fiscal']::public.verification_step[], false, 'comissao_primeiro_servico'::public.billing_model, true, false, 'autonomo_ou_empresa'::public.provider_kind, false, array['hora', 'mes', 'projeto', 'visita']::public.price_unit[], array['online', 'estabelecimento', 'empresa_cliente']::public.service_location[], 'Boas práticas, APPCC e treinamento de manipuladores. Registro no CRN, CREA, CRMV ou CRQ é opcional e informado pelo profissional. Não substitui licença sanitária nem inspeção.', 'a_confirmar', '{}'::text[]),
  ('telenutricao', true, 'CFN/CRN', 'CRN', 'Lei 8.234/1991, art. 1º; Res. CFN 760/2023, arts. 1º, 2º e 5º; Lei 14.510/2022 (Lei 8.080/1990, arts. 26-A a 26-H)', array['documento_selfie', 'cadastro_fiscal', 'registro_profissional', 'licenca_orgao']::public.verification_step[], false, 'so_assinatura'::public.billing_model, false, false, 'autonomo'::public.provider_kind, false, array['sessao', 'mes', 'pacote']::public.price_unit[], array['online']::public.service_location[], 'Exige CRN ativo e inscrição no e-Nutricionista (Res. CFN 760/2023, art. 5º). Honorários e promoções não podem ser usados como publicidade (art. 12, §1º). Comissão de plataforma: norma do CFN não localizada nas lidas.', 'conferido', array['https://www2.camara.leg.br/legin/fed/lei/1991/lei-8234-17-setembro-1991-363145-publicacaooriginal-1-pl.html', 'http://legis.senado.leg.br/norma/36665930/publicacao/36672979', 'https://sisnormas.cfn.org.br/viewPage.html?id=760']::text[]),
