  ('enfermeiro-obstetra-e-parteira', true, 'COFEN/COREN', 'COREN', 'Lei 7.498/1986 (arts. 6, II, 9 e 11, parágrafo único); Decreto 94.406/1987 (arts. 4, II, 9 e 12)', array['documento_selfie', 'cadastro_fiscal', 'registro_profissional', 'antecedentes']::public.verification_step[], true, 'sob_consulta_juridica'::public.billing_model, true, false, 'autonomo_ou_empresa'::public.provider_kind, false, array['servico', 'sessao', 'pacote', 'visita']::public.price_unit[], array['domicilio', 'online', 'estabelecimento']::public.service_location[], 'Pré-natal e assistência ao parto normal por enfermeira obstétrica, obstetriz ou parteira com COREN (Lei 7.498/1986, arts. 6, II, e 11). Parto em domicílio: sempre que possível sob controle de unidade de saúde (Decreto 94.406/1987, art. 12).', 'conferido', array['https://www2.camara.leg.br/legin/fed/lei/1980-1987/lei-7498-25-junho-1986-368005-publicacaooriginal-1-pl.html', 'https://www2.camara.leg.br/legin/fed/decret/1980-1987/decreto-94406-8-junho-1987-444430-publicacaooriginal-1-pe.html']::text[]),
  ('enfermagem-do-trabalho', true, 'COFEN/COREN', 'COREN', 'Lei 7.498/1986 (arts. 2 e 11); Decreto 94.406/1987 (arts. 1 e 8); Res. Cofen 581/2018 (art. 1; Anexo, item 38, Saúde do Trabalhador/Ocupacional)', array['documento_selfie', 'cadastro_fiscal', 'registro_profissional', 'certificado_curso']::public.verification_step[], false, 'sob_consulta_juridica'::public.billing_model, true, false, 'autonomo_ou_empresa'::public.provider_kind, false, array['hora', 'mes', 'projeto', 'visita']::public.price_unit[], array['online', 'estabelecimento', 'empresa_cliente']::public.service_location[], 'Atua em programas de saúde ocupacional, com título de especialista registrado no COREN. Comissão em análise jurídica.', 'a_confirmar', array['https://www2.camara.leg.br/legin/fed/lei/1980-1987/lei-7498-25-junho-1986-368005-publicacaooriginal-1-pl.html', 'https://www2.camara.leg.br/legin/fed/decret/1980-1987/decreto-94406-8-junho-1987-444430-publicacaooriginal-1-pe.html', 'https://abmes.org.br/public/arquivos/legislacoes/Resolucao-Cofen-581-2018-07-11.pdf']::text[]),
  ('estomaterapia', true, 'COFEN/COREN', 'COREN', 'Lei 7.498/1986 (arts. 2 e 11); Decreto 94.406/1987 (arts. 1 e 8); Res. Cofen 581/2018 (art. 1; Anexo, item 16, Estomaterapia)', array['documento_selfie', 'cadastro_fiscal', 'registro_profissional', 'antecedentes', 'certificado_curso']::public.verification_step[], true, 'sob_consulta_juridica'::public.billing_model, true, false, 'autonomo_ou_empresa'::public.provider_kind, false, array['servico', 'sessao', 'pacote', 'visita']::public.price_unit[], array['domicilio', 'online', 'estabelecimento']::public.service_location[], 'Cuidado de feridas, estomias e incontinências por enfermeiro com título de especialista registrado no COREN. Prescrição de medicamentos segue protocolo e orientação médica.', 'a_confirmar', array['https://www2.camara.leg.br/legin/fed/lei/1980-1987/lei-7498-25-junho-1986-368005-publicacaooriginal-1-pl.html', 'https://www2.camara.leg.br/legin/fed/decret/1980-1987/decreto-94406-8-junho-1987-444430-publicacaooriginal-1-pe.html', 'https://abmes.org.br/public/arquivos/legislacoes/Resolucao-Cofen-581-2018-07-11.pdf']::text[]),
  ('enfermagem-em-urgencia-e-emergencia', true, 'COFEN/COREN', 'COREN', 'Lei 7.498/1986 (arts. 2 e 11); Decreto 94.406/1987 (arts. 1 e 8); Res. Cofen 581/2018 (art. 1; Anexo, item 46, Urgência e Emergência)', array['documento_selfie', 'cadastro_fiscal', 'registro_profissional']::public.verification_step[], false, 'sob_consulta_juridica'::public.billing_model, true, false, 'autonomo_ou_empresa'::public.provider_kind, false, array['hora', 'plantao', 'evento']::public.price_unit[], array['estabelecimento', 'empresa_cliente', 'externo']::public.service_location[], 'Cobertura de eventos e apoio a serviços de urgência por enfermeiro com COREN. Remoção em ambulância e UTI móvel fica fora desta ocupação.', 'a_confirmar', array['https://www2.camara.leg.br/legin/fed/lei/1980-1987/lei-7498-25-junho-1986-368005-publicacaooriginal-1-pl.html', 'https://www2.camara.leg.br/legin/fed/decret/1980-1987/decreto-94406-8-junho-1987-444430-publicacaooriginal-1-pe.html', 'https://abmes.org.br/public/arquivos/legislacoes/Resolucao-Cofen-581-2018-07-11.pdf']::text[]),
  ('enfermagem-em-terapia-intensiva', true, 'COFEN/COREN', 'COREN', 'Lei 7.498/1986 (arts. 2 e 11, I, l); Decreto 94.406/1987 (arts. 1 e 8, I, g); Res. Cofen 581/2018 (art. 1; Anexo, item 43)', array['documento_selfie', 'cadastro_fiscal', 'registro_profissional', 'certificado_curso']::public.verification_step[], false, 'sob_consulta_juridica'::public.billing_model, true, false, 'autonomo_ou_empresa'::public.provider_kind, false, array['hora', 'plantao', 'mes']::public.price_unit[], array['estabelecimento', 'empresa_cliente']::public.service_location[], 'Cuidado a pacientes graves por enfermeiro com título de especialista, em serviço de saúde contratante. UTI domiciliar fica fora desta ocupação (ver Home care).', 'a_confirmar', array['https://www2.camara.leg.br/legin/fed/lei/1980-1987/lei-7498-25-junho-1986-368005-publicacaooriginal-1-pl.html', 'https://www2.camara.leg.br/legin/fed/decret/1980-1987/decreto-94406-8-junho-1987-444430-publicacaooriginal-1-pe.html', 'https://abmes.org.br/public/arquivos/legislacoes/Resolucao-Cofen-581-2018-07-11.pdf']::text[]),
  ('enfermagem-em-saude-da-familia', true, 'COFEN/COREN', 'COREN', 'Lei 7.498/1986 (arts. 2 e 11); Decreto 94.406/1987 (arts. 1 e 8); Res. Cofen 581/2018 (art. 1; Anexo, item 33, a (Saúde da Família e Comunidade))', array['documento_selfie', 'cadastro_fiscal', 'registro_profissional', 'antecedentes']::public.verification_step[], true, 'sob_consulta_juridica'::public.billing_model, true, false, 'autonomo_ou_empresa'::public.provider_kind, false, array['hora', 'sessao', 'pacote', 'visita']::public.price_unit[], array['domicilio', 'online', 'estabelecimento']::public.service_location[], 'Atenção primária, visita domiciliar e acompanhamento de doenças crônicas por enfermeiro com COREN. Prescrever medicamento só em programa de saúde pública ou rotina aprovada pela instituição.', 'a_confirmar', array['https://www2.camara.leg.br/legin/fed/lei/1980-1987/lei-7498-25-junho-1986-368005-publicacaooriginal-1-pl.html', 'https://www2.camara.leg.br/legin/fed/decret/1980-1987/decreto-94406-8-junho-1987-444430-publicacaooriginal-1-pe.html', 'https://abmes.org.br/public/arquivos/legislacoes/Resolucao-Cofen-581-2018-07-11.pdf']::text[]),
  ('enfermagem-em-saude-mental', true, 'COFEN/COREN', 'COREN', 'Lei 7.498/1986 (arts. 2 e 11); Decreto 94.406/1987 (arts. 1 e 8); Res. Cofen 581/2018 (art. 1; Anexo, item 40 (Saúde Mental))', array['documento_selfie', 'cadastro_fiscal', 'registro_profissional', 'antecedentes']::public.verification_step[], true, 'sob_consulta_juridica'::public.billing_model, true, false, 'autonomo_ou_empresa'::public.provider_kind, false, array['hora', 'sessao', 'pacote', 'visita']::public.price_unit[], array['domicilio', 'online', 'estabelecimento']::public.service_location[], 'Cuidado de enfermagem a pessoas em sofrimento psíquico, com antecedentes por atender público vulnerável. Não substitui psicoterapia nem prescrição médica; crises graves vão à rede de saúde.', 'a_confirmar', array['https://www2.camara.leg.br/legin/fed/lei/1980-1987/lei-7498-25-junho-1986-368005-publicacaooriginal-1-pl.html', 'https://www2.camara.leg.br/legin/fed/decret/1980-1987/decreto-94406-8-junho-1987-444430-publicacaooriginal-1-pe.html', 'https://abmes.org.br/public/arquivos/legislacoes/Resolucao-Cofen-581-2018-07-11.pdf']::text[]),
  ('enfermagem-em-reabilitacao', true, 'COFEN/COREN', 'COREN', 'Lei 7.498/1986; Decreto 94.406/1987; Res. Cofen 581/2018 (Anexo, item 51)', array['documento_selfie', 'cadastro_fiscal', 'registro_profissional', 'antecedentes']::public.verification_step[], true, 'sob_consulta_juridica'::public.billing_model, true, true, 'autonomo_ou_empresa'::public.provider_kind, false, array['hora', 'sessao', 'pacote', 'visita']::public.price_unit[], array['domicilio', 'online', 'estabelecimento']::public.service_location[], 'Cuidado a pessoas com deficiência ou perda de função, junto à fisioterapia e à terapia ocupacional. Título no COREN. Na mesma casa, até 2 dias por semana (LC 150/2015).', 'conferido', array['https://www.planalto.gov.br/ccivil_03/decreto/1980-1989/d94406.htm', 'https://www.cofen.gov.br/resolucao-cofen-no-581-2018/']::text[]),
  ('enfermagem-em-estetica', true, 'COFEN/COREN', 'COREN', 'Lei 7.498/1986 (arts. 2 e 11); Decreto 94.406/1987 (arts. 1 e 8); Res. Cofen 581/2018 (art. 1; Anexo, item 15 (Estética))', array['documento_selfie', 'cadastro_fiscal', 'registro_profissional']::public.verification_step[], false, 'sob_consulta_juridica'::public.billing_model, true, false, 'autonomo_ou_empresa'::public.provider_kind, false, array['servico', 'sessao', 'pacote']::public.price_unit[], array['estabelecimento']::public.service_location[], 'Enquanto não houver parecer jurídico, a oferta fica limitada a atos não invasivos. Sem comissão por ora.', 'a_confirmar', array['https://www2.camara.leg.br/legin/fed/lei/1980-1987/lei-7498-25-junho-1986-368005-publicacaooriginal-1-pl.html', 'https://www2.camara.leg.br/legin/fed/decret/1980-1987/decreto-94406-8-junho-1987-444430-publicacaooriginal-1-pe.html', 'https://abmes.org.br/public/arquivos/legislacoes/Resolucao-Cofen-581-2018-07-11.pdf']::text[]),
  ('podiatria-clinica', true, 'COFEN/COREN', 'COREN', 'Lei 7.498/1986; Decreto 94.406/1987; Res. Cofen 581/2018 (Anexo, item 50)', array['documento_selfie', 'cadastro_fiscal', 'registro_profissional', 'antecedentes']::public.verification_step[], true, 'sob_consulta_juridica'::public.billing_model, true, false, 'autonomo_ou_empresa'::public.provider_kind, false, array['servico', 'sessao', 'pacote', 'visita']::public.price_unit[], array['domicilio', 'estabelecimento']::public.service_location[], 'Cuidado clínico dos pés por enfermeiro com título de podiatria no COREN. Não é a profissão de podólogo, que não tem lei federal. Comissão em análise jurídica.', 'conferido', array['https://www.cofen.gov.br/resolucao-cofen-no-581-2018/']::text[]),
  ('enfermagem-nuclear', true, 'COFEN/COREN', 'COREN', 'Lei 7.498/1986; Decreto 94.406/1987; Res. Cofen 581/2018 (Anexo, item 49)', array['documento_selfie', 'cadastro_fiscal', 'registro_profissional']::public.verification_step[], false, 'sob_consulta_juridica'::public.billing_model, true, false, 'autonomo_ou_empresa'::public.provider_kind, false, array['hora', 'plantao', 'mes']::public.price_unit[], array['estabelecimento', 'empresa_cliente']::public.service_location[], 'Atua em serviços de medicina nuclear com título de especialista no COREN. O serviço contratante responde pelo licenciamento nuclear e sanitário. Comissão em análise jurídica.', 'conferido', array['https://www.cofen.gov.br/resolucao-cofen-no-581-2018/']::text[]),
  ('enfermagem-em-informatica-em-saude', true, 'COFEN/COREN', 'COREN', 'Lei 7.498/1986 (art. 2); Res. Cofen 581/2018 (art. 1; Anexo, Área II, item 5); Res. Cofen 554/2017 (art. 3, §1; cópia Conass)', array['documento_selfie', 'cadastro_fiscal', 'registro_profissional', 'certificado_curso']::public.verification_step[], false, 'sob_consulta_juridica'::public.billing_model, true, false, 'autonomo_ou_empresa'::public.provider_kind, false, array['hora', 'mes', 'projeto']::public.price_unit[], array['online', 'empresa_cliente']::public.service_location[], 'Consultoria em prontuário e sistemas de saúde, sem atender pacientes. COREN é exigido de quem se apresenta como enfermeiro especialista. Dados de saúde só com contrato e LGPD.', 'a_confirmar', array['https://abmes.org.br/public/arquivos/legislacoes/Resolucao-Cofen-581-2018-07-11.pdf', 'https://www.conass.org.br/?p=10865', 'https://www2.camara.leg.br/legin/fed/lei/1980-1987/lei-7498-25-junho-1986-368005-publicacaooriginal-1-pl.html']::text[]),
  ('aplicacao-de-injetaveis-e-curativos-a-domicilio', true, 'COFEN/COREN', 'COREN', 'Lei 7.498/1986 (arts. 2 e 11); Decreto 94.406/1987 (arts. 1, 10, 11, III e 13)', array['documento_selfie', 'cadastro_fiscal', 'registro_profissional', 'antecedentes']::public.verification_step[], true, 'sob_consulta_juridica'::public.billing_model, true, false, 'autonomo_ou_empresa'::public.provider_kind, false, array['servico', 'pacote', 'visita']::public.price_unit[], array['domicilio']::public.service_location[], 'Só enfermeiro, técnico ou auxiliar com COREN aplica injetáveis, com tratamento prescrito ou de rotina (Decreto 94.406/1987, art. 11, III). Técnico e auxiliar sob supervisão do enfermeiro (art. 13). Leigo não pode ofertar.', 'conferido', array['https://www2.camara.leg.br/legin/fed/lei/1980-1987/lei-7498-25-junho-1986-368005-publicacaooriginal-1-pl.html', 'https://www2.camara.leg.br/legin/fed/decret/1980-1987/decreto-94406-8-junho-1987-444430-publicacaooriginal-1-pe.html']::text[]),
  ('vacinacao-domiciliar', true, 'Vigilância sanitária (Anvisa) e COREN', 'Licença sanitária', 'Lei 7.498/1986; RDC Anvisa 197/2017', array['documento_selfie', 'cadastro_fiscal', 'registro_profissional', 'antecedentes', 'licenca_orgao']::public.verification_step[], true, 'sob_consulta_juridica'::public.billing_model, true, false, 'somente_empresa_licenciada'::public.provider_kind, true, array['servico', 'pacote', 'visita']::public.price_unit[], array['domicilio', 'empresa_cliente']::public.service_location[], 'Só serviço de vacinação com licença sanitária, responsável técnico e cadeia de frio; vacinas de origem regular. Menores só com responsável presente. Comissão em análise jurídica.', 'a_confirmar', array['https://www.planalto.gov.br/ccivil_03/decreto/1980-1989/d94406.htm']::text[]),
  ('home-care', true, 'Vigilância sanitária (Anvisa) e COREN', 'Licença sanitária', 'RDC Anvisa 11/2006 (art. 2; Anexo: alvará e responsável técnico de nível superior); Res. Cofen 581/2018 (art. 1; Anexo, item 5, a)', array['documento_selfie', 'cadastro_fiscal', 'registro_profissional', 'antecedentes', 'licenca_orgao']::public.verification_step[], true, 'sob_consulta_juridica'::public.billing_model, true, false, 'somente_empresa_licenciada'::public.provider_kind, false, array['dia', 'plantao', 'mes', 'pacote']::public.price_unit[], array['domicilio']::public.service_location[], 'Só serviço de atenção domiciliar licenciado pela autoridade sanitária local, com responsável técnico de nível superior (RDC 11/2006, art. 2 e Anexo). Sem internação domiciliar na plataforma.', 'a_confirmar', array['https://bvsms.saude.gov.br/bvs/saudelegis/anvisa/2006/rdc0011_26_01_2006.html', 'https://abmes.org.br/public/arquivos/legislacoes/Resolucao-Cofen-581-2018-07-11.pdf', 'https://www.cofen.gov.br/parecer-de-conselheiro-federal', 'https://www.cofen.gov.br/resolucao-cofen-no-581-2018/', 'https://www.cofen.gov.br/lei-n-749886-de-25-de-junho-de-1986']::text[]),
