  ('termalismo-e-crenoterapia', true, 'ANM; vigilância sanitária', 'Concessão de lavra e licença sanitária', 'Decreto-Lei 7.841/1945 (Código de Águas Minerais); Portaria MS 971/2006 (PNPIC)', array['documento_selfie', 'cadastro_fiscal', 'registro_profissional', 'licenca_orgao']::public.verification_step[], false, 'comissao_primeiro_servico'::public.billing_model, true, false, 'somente_empresa_licenciada'::public.provider_kind, false, array['dia', 'sessao', 'pacote']::public.price_unit[], array['estabelecimento', 'externo']::public.service_location[], 'Só estabelecimento com água mineral autorizada e licença sanitária. Uso complementar, sem promessa de cura nem substituição de tratamento médico. Normas a confirmar.', 'a_confirmar', '{}'::text[]),
