  ('filosofia-clinica-e-aconselhamento-filosofico', false, '', '', '', array['documento_selfie', 'cadastro_fiscal']::public.verification_step[], false, 'comissao_primeiro_servico'::public.billing_model, true, false, 'autonomo'::public.provider_kind, false, array['sessao', 'mes', 'pacote']::public.price_unit[], array['online', 'estabelecimento']::public.service_location[], 'Não é psicoterapia nem tratamento de saúde; vedado usar título de psicólogo ou médico, diagnosticar ou prescrever. Sem regulamentação por lei federal confirmada.', 'a_confirmar', '{}'::text[]),
  ('personal-trainer', true, 'CONFEF/CREF', 'CREF', 'Lei 9.696/1998, arts. 1º e 3º (red. Lei 14.386/2022); Res. CONFEF 488/2023, art. 4º, I, III e VII; Res. CONFEF 542/2024 (à distância); Código de Ética (Res. CONFEF 508/2023), arts. 4º e 5º, IV', array['documento_selfie', 'cadastro_fiscal', 'registro_profissional', 'antecedentes']::public.verification_step[], true, 'sob_consulta_juridica'::public.billing_model, true, false, 'autonomo'::public.provider_kind, false, array['hora', 'sessao', 'mes', 'pacote']::public.price_unit[], array['domicilio', 'online', 'estabelecimento', 'externo']::public.service_location[], 'Exige CREF ativo para prescrever exercícios (Lei 9.696/1998, art. 3º). O anúncio leva nome e nº do CREF (Código de Ética, art. 4º). Atendimento online segue a Res. CONFEF 542/2024. Treino na casa do cliente exige checagem de antecedentes.', 'conferido', array['https://www2.camara.leg.br/legin/fed/lei/1998/lei-9696-1-setembro-1998-374623-normaatualizada-pl.pdf', 'https://www.confef.org.br/resolucoes/573', 'https://www.confef.org.br/resolucoes/592', 'https://www.confef.org.br/resolucoes/627', 'https://www.confef.org.br/resolucoes/704']::text[]),
