  ('culinaria-vegana-e-sem-gluten', true, 'Vigilância sanitária (município/estado)', 'Licença sanitária', 'Lei 6.437/1977; RDC Anvisa 216/2004; Portaria CVS 5/2013 (SP)', array['documento_selfie', 'cadastro_fiscal', 'registro_profissional', 'licenca_orgao']::public.verification_step[], false, 'comissao_primeiro_servico'::public.billing_model, true, false, 'autonomo_ou_empresa'::public.provider_kind, false, array['servico', 'mes', 'pacote', 'evento']::public.price_unit[], array['domicilio', 'estabelecimento', 'empresa_cliente']::public.service_location[], 'Serviço de alimentação: exige licença sanitária (RDC 216/2004). Informar alergênicos e risco de contaminação cruzada. Não prescreve dieta clínica (atividade de nutricionista).', 'a_confirmar', '{}'::text[]),
