  ('instalador-de-paineis-publicitarios', false, '', '', '', array['documento_selfie', 'cadastro_fiscal', 'certificado_curso']::public.verification_step[], false, 'comissao_primeiro_servico'::public.billing_model, true, false, 'autonomo_ou_empresa'::public.provider_kind, false, array['dia', 'servico', 'm2']::public.price_unit[], array['empresa_cliente', 'externo']::public.service_location[], 'Trabalho em altura exige treinamento da NR-35. Painéis e outdoors dependem de licença municipal, em geral do dono da mídia (SP: Lei 14.223/2006).', 'a_confirmar', '{}'::text[]),
  ('serigrafista', false, '', '', '', array['documento_selfie', 'cadastro_fiscal']::public.verification_step[], false, 'comissao_primeiro_servico'::public.billing_model, true, false, 'autonomo_ou_empresa'::public.provider_kind, false, array['servico', 'projeto', 'pacote']::public.price_unit[], array['online', 'estabelecimento']::public.service_location[], 'Produção sob encomenda, por tiragem. Marcas e personagens de terceiros exigem autorização do titular; resíduos de tinta seguem as regras ambientais.', 'a_confirmar', '{}'::text[]),
