  ('alfaiate', false, '', '', '', array['documento_selfie', 'cadastro_fiscal']::public.verification_step[], false, 'comissao_primeiro_servico'::public.billing_model, true, false, 'autonomo_ou_empresa'::public.provider_kind, false, array['servico', 'projeto', 'pacote']::public.price_unit[], array['estabelecimento', 'empresa_cliente']::public.service_location[], 'Roupas sob medida, com provas e prazo registrados no orçamento. Sem registro profissional obrigatório.', 'a_confirmar', '{}'::text[]),
  ('vestido-de-noiva-sob-medida', false, '', '', '', array['documento_selfie', 'cadastro_fiscal']::public.verification_step[], false, 'comissao_primeiro_servico'::public.billing_model, true, false, 'autonomo_ou_empresa'::public.provider_kind, false, array['servico', 'projeto', 'pacote']::public.price_unit[], array['estabelecimento']::public.service_location[], 'Peça de alto valor feita por encomenda: contrato com prazo, provas, sinal e regras de alteração. Sem registro profissional obrigatório.', 'a_confirmar', '{}'::text[]),
