  ('design-de-moda', false, '', '', '', array['documento_selfie', 'cadastro_fiscal']::public.verification_step[], false, 'comissao_primeiro_servico'::public.billing_model, true, false, 'autonomo_ou_empresa'::public.provider_kind, false, array['hora', 'projeto', 'pacote']::public.price_unit[], array['online', 'estabelecimento', 'empresa_cliente']::public.service_location[], 'Contratado por projeto ou coleção; o contrato define a titularidade de desenhos e modelagens. Sem registro profissional obrigatório.', 'a_confirmar', '{}'::text[]),
  ('modelista', false, '', '', '', array['documento_selfie', 'cadastro_fiscal']::public.verification_step[], false, 'comissao_primeiro_servico'::public.billing_model, true, false, 'autonomo_ou_empresa'::public.provider_kind, false, array['hora', 'servico', 'projeto', 'pacote']::public.price_unit[], array['online', 'estabelecimento', 'empresa_cliente']::public.service_location[], 'Contratado por molde, peça-piloto ou projeto; o contrato define a titularidade dos moldes. Sem registro profissional obrigatório.', 'a_confirmar', '{}'::text[]),
  ('personal-stylist-e-consultoria-de-imagem', false, '', '', '', array['documento_selfie', 'cadastro_fiscal', 'antecedentes']::public.verification_step[], true, 'comissao_primeiro_servico'::public.billing_model, true, false, 'autonomo_ou_empresa'::public.provider_kind, false, array['hora', 'sessao', 'pacote']::public.price_unit[], array['domicilio', 'online', 'estabelecimento', 'empresa_cliente']::public.service_location[], 'Pode atender no guarda-roupa do cliente, em casa: antecedentes exigidos. Sem registro profissional obrigatório; contratação por sessão ou pacote.', 'a_confirmar', '{}'::text[]),
